export function articleBody(locale:Locale,slug:string):Body{
 if(locale==="en")return enBodies[slug];
 const base=compactBodies[locale][slug];
 const target=enBodies[slug].sections.length;
 const additions=(extraSections[locale]?.[slug]||[]).slice(0,Math.max(0,target-base.sections.length));
 return {...base,sections:[...base.sections,...additions]};
}

